defmodule Tymeslot.Repo.Migrations.CreateBookingPagesTest do
  @moduledoc """
  Covers the booking pages migration where it touches existing rows: the
  deduplication guard ahead of the partial unique index on
  `theme_customizations`, the indexes it leaves behind, and a rollback that
  must survive page-level customisations. See `Tymeslot.Test.MigrationRunner`.
  """

  use Tymeslot.DataCase, async: false

  @moduletag :database
  @moduletag :themes
  @moduletag :migrations

  alias Tymeslot.Repo
  alias Tymeslot.Test.MigrationRunner

  # Generated by `mix ecto.gen.migration create_booking_pages`.
  @version 20_261_029_120_000

  @index "theme_customizations_profile_id_theme_id_index"

  setup do
    {:ok, profile: insert(:profile), other: insert(:profile)}
  end

  describe "deduplication guard" do
    test "keeps only the most recently updated row per profile and theme", ctx do
      pre_migration_schema()

      oldest = insert_customization(ctx.profile.id, "1", "2026-01-01 10:00:00")
      newest = insert_customization(ctx.profile.id, "1", "2026-03-01 10:00:00")
      middle = insert_customization(ctx.profile.id, "1", "2026-02-01 10:00:00")
      other_theme = insert_customization(ctx.profile.id, "2", "2026-01-01 10:00:00")
      other_profile = insert_customization(ctx.other.id, "1", "2026-01-01 10:00:00")

      MigrationRunner.up!(@version)

      remaining = customization_ids()
      assert newest in remaining
      assert other_theme in remaining
      assert other_profile in remaining
      refute oldest in remaining
      refute middle in remaining
      assert length(remaining) == 3
    end

    test "breaks a tie on updated_at by keeping the highest id", ctx do
      pre_migration_schema()

      ids = for _n <- 1..3, do: insert_customization(ctx.profile.id, "1", "2026-01-01 10:00:00")

      MigrationRunner.up!(@version)

      assert customization_ids() == [Enum.max(ids)]
    end
  end

  describe "indexes after up" do
    setup ctx do
      pre_migration_schema()
      MigrationRunner.up!(@version)
      {:ok, ctx}
    end

    test "a second profile-level row for the same profile and theme is rejected", ctx do
      insert_customization(ctx.profile.id, "1", "2026-01-01 10:00:00")

      assert {:error, %Postgrex.Error{postgres: %{code: :unique_violation, constraint: @index}}} =
               try_insert_customization(ctx.profile.id, "1", nil)
    end

    test "a page-level row is admitted beside the profile's row", ctx do
      profile_row = insert_customization(ctx.profile.id, "1", "2026-01-01 10:00:00")
      page_id = insert_page(ctx.profile.id, "events")

      assert {:ok, page_row} = try_insert_customization(ctx.profile.id, "1", page_id)
      assert page_row != profile_row
    end

    test "a page has one customisation per theme", ctx do
      page_id = insert_page(ctx.profile.id, "events")
      assert {:ok, _result} = try_insert_customization(ctx.profile.id, "1", page_id)

      assert {:error, %Postgrex.Error{postgres: %{code: :unique_violation}}} =
               try_insert_customization(ctx.profile.id, "1", page_id)

      assert {:ok, _result} = try_insert_customization(ctx.profile.id, "2", page_id)
    end
  end

  test "rolling back and migrating again keeps the profile's rows over page rows", ctx do
    MigrationRunner.down!(@version)
    MigrationRunner.up!(@version)

    profile_row = insert_customization(ctx.profile.id, "1", "2026-01-01 10:00:00")
    page_id = insert_page(ctx.profile.id, "events")
    {:ok, page_row} = try_insert_customization(ctx.profile.id, "1", page_id)

    MigrationRunner.down!(@version)

    assert customization_ids() == [profile_row]
    refute page_row in customization_ids()

    MigrationRunner.up!(@version)

    assert customization_ids() == [profile_row]

    assert {:error, %Postgrex.Error{postgres: %{code: :unique_violation}}} =
             try_insert_customization(ctx.profile.id, "1", nil)
  end

  # Rolls the migration back and drops the full unique index the rollback
  # restores, as a database that lost it would be.
  defp pre_migration_schema do
    MigrationRunner.down!(@version)
    Repo.query!("DROP INDEX theme_customizations_profile_id_theme_id_index")
  end

  # Takes the updated_at as a string; the page column only exists after up.
  defp insert_customization(profile_id, theme_id, updated_at) do
    %{rows: [[id]]} =
      Repo.query!(
        """
        INSERT INTO theme_customizations
          (profile_id, theme_id, settings, video_processing_status, inserted_at, updated_at)
        VALUES ($1, $2, '{}', '{}', $3, $3)
        RETURNING id
        """,
        [
          profile_id,
          theme_id,
          DateTime.from_naive!(NaiveDateTime.from_iso8601!(updated_at), "Etc/UTC")
        ]
      )

    id
  end

  defp try_insert_customization(profile_id, theme_id, page_id) do
    # A savepoint keeps the sandbox transaction usable after a violation.
    Repo.transaction(fn ->
      case Repo.query(
             """
             INSERT INTO theme_customizations
               (profile_id, theme_id, booking_page_id, settings, video_processing_status,
                inserted_at, updated_at)
             VALUES ($1, $2, $3, '{}', '{}', now(), now())
             RETURNING id
             """,
             [profile_id, theme_id, page_id]
           ) do
        {:ok, %{rows: [[id]]}} -> id
        {:error, error} -> Repo.rollback(error)
      end
    end)
  end

  defp insert_page(profile_id, slug) do
    %{rows: [[id]]} =
      Repo.query!(
        """
        INSERT INTO booking_pages (profile_id, slug, name, booking_theme, inserted_at, updated_at)
        VALUES ($1, $2, $2, '1', now(), now())
        RETURNING id
        """,
        [profile_id, slug]
      )

    id
  end

  defp customization_ids do
    %{rows: rows} = Repo.query!("SELECT id FROM theme_customizations ORDER BY id")
    Enum.map(rows, &hd/1)
  end
end
